	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "child-001", "parent_id": "parent-A"}`),
		json.RawMessage(`{"id": "child-002", "parent_id": "parent-A"}`),
		json.RawMessage(`{"id": "child-003", "parent_id": "parent-B"}`),
	}
	if _, _, err := s.UpsertBatch("device_control", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}

	db := s.DB()

	var matchedA int
	parentQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s" WHERE parent_id = ?`, "device_control")
